"""Shared eval helpers. Gold labels are human-written, not generated by MockBackend."""

from __future__ import annotations

from collections import Counter, defaultdict
from typing import Any

from laya_thalamus import AgentRouter
from laya_thalamus.schemas import RouteDecision


def confusion(y_true: list[str], y_pred: list[str]) -> dict[str, dict[str, int]]:
    labels = sorted(set(y_true) | set(y_pred))
    matrix: dict[str, dict[str, int]] = {a: {b: 0 for b in labels} for a in labels}
    for t, p in zip(y_true, y_pred):
        matrix[t][p] += 1
    return matrix


def predicted_tool(d: RouteDecision) -> str:
    pred = d.selected_tool or "none"
    if d.action.value == "answer" and pred in (None, "none"):
        return "none"
    return pred


def evaluate_items(router: AgentRouter, data: list[dict[str, Any]]) -> dict[str, Any]:
    y_true: list[str] = []
    y_pred: list[str] = []
    action_ok = 0
    action_n = 0
    suff_ok = 0
    suff_n = 0
    score_ok = 0
    score_n = 0
    errors: list[dict[str, Any]] = []
    latencies: list[float] = []
    fallback_hits = 0

    for item in data:
        d = router.route(
            item["query"],
            context=item.get("context"),
            tool_result=item.get("tool_result"),
            history=item.get("history") or [],
        )
        latencies.append(d.latency_ms)
        if d.fallback_used:
            fallback_hits += 1
        pred_tool = predicted_tool(d)
        exp_tool = item["expected_tool"]
        y_true.append(exp_tool)
        y_pred.append(pred_tool)

        if "expected_action" in item:
            action_n += 1
            if d.action.value == item["expected_action"]:
                action_ok += 1

        if "expected_sufficient" in item and d.information_sufficient is not None:
            suff_n += 1
            if bool(d.information_sufficient) == bool(item["expected_sufficient"]):
                suff_ok += 1

        if "expected_score_min" in item and d.credibility_score is not None:
            score_n += 1
            lo = float(item["expected_score_min"])
            hi = float(item.get("expected_score_max", 10))
            if lo <= d.credibility_score <= hi:
                score_ok += 1

        if pred_tool != exp_tool:
            errors.append(
                {
                    "id": item.get("id"),
                    "query": item["query"],
                    "expected": exp_tool,
                    "predicted": pred_tool,
                    "action": d.action.value,
                    "confidence": d.confidence,
                    "latency_ms": round(d.latency_ms, 2),
                    "fallback_used": d.fallback_used,
                    "backend": d.backend,
                    "category": item.get("category"),
                }
            )

    n = len(data)
    tool_correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    by_cat: dict[str, list[bool]] = defaultdict(list)
    for item, t, p in zip(data, y_true, y_pred):
        by_cat[item.get("category", "other")].append(t == p)

    avg_lat = sum(latencies) / len(latencies) if latencies else 0.0
    return {
        "n": n,
        "tool_accuracy": round(tool_correct / n, 4) if n else 0.0,
        "action_accuracy": round(action_ok / action_n, 4) if action_n else None,
        "noul_accuracy": round(suff_ok / suff_n, 4) if suff_n else None,
        "score_band_accuracy": round(score_ok / score_n, 4) if score_n else None,
        "per_category_accuracy": {k: round(sum(v) / len(v), 4) for k, v in by_cat.items()},
        "confusion_matrix": confusion(y_true, y_pred),
        "tool_distribution_pred": dict(Counter(y_pred)),
        "avg_latency_ms": round(avg_lat, 2),
        "backend": router.backend.name,
        "error_count": len(errors),
        "fallback_count": fallback_hits,
        "fallback_rate": round(fallback_hits / n, 4) if n else 0.0,
        "errors": errors,
        "caveat": (
            "If backend=mock, tool_accuracy measures the keyword heuristic against "
            "human labels -it is NOT a Laya model metric."
        ),
    }
